function cheapestFare(n: number, flights: number[][], src: number, dst: number, k: number): number {
  const out: number[][][] = Array.from({ length: n }, () => []);
  for (const [u, v, p] of flights) out[u].push([v, p]);
  let best = Infinity;
  const dfs = (city: number, flightsLeft: number, spent: number): void => {
    if (spent >= best) return;
    if (city === dst) { best = spent; return; }
    if (flightsLeft === 0) return;
    for (const [v, p] of out[city]) dfs(v, flightsLeft - 1, spent + p);
  };
  dfs(src, k + 1, 0);
  return best === Infinity ? -1 : best;
}

