function cheapestFare(n: number, flights: number[][], src: number, dst: number, k: number): number {
  let price = new Array(n).fill(Infinity);
  price[src] = 0;
  for (let round = 0; round <= k; round++) {
    const next = price.slice(); // read from price, write to next: one flight per round
    for (const [u, v, p] of flights) {
      if (price[u] + p < next[v]) next[v] = price[u] + p;
    }
    price = next;
  }
  return price[dst] === Infinity ? -1 : price[dst];
}

