class Heap<T> {
  private a: T[] = [];
  constructor(private before: (x: T, y: T) => boolean) {}
  get size(): number { return this.a.length; }
  push(x: T): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.before(a[i], a[p])) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): T {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.before(a[l], a[m])) m = l;
        if (r < a.length && this.before(a[r], a[m])) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function cheapestFare(n: number, flights: number[][], src: number, dst: number, k: number): number {
  const out: number[][][] = Array.from({ length: n }, () => []);
  for (const [u, v, p] of flights) out[u].push([v, p]);
  const fewest = new Array(n).fill(Infinity); // fewest flights of any entry already expanded
  const heap = new Heap<number[]>((x, y) => x[0] < y[0]); // [price, city, flights used]
  heap.push([0, src, 0]);
  while (heap.size) {
    const [cost, city, used] = heap.pop();
    if (city === dst) return cost;
    // an earlier pop was at most as cheap and used no more flights: this entry is dominated
    if (used >= fewest[city]) continue;
    fewest[city] = used;
    if (used === k + 1) continue;
    for (const [v, p] of out[city]) heap.push([cost + p, v, used + 1]);
  }
  return -1;
}

